const CACHE_NAME = "epl-predictor-v3";

// Hashed bundles under /assets/ are immutable, but the rest of the cache is
// not: visuals/*.png, badges/*.png and the header logo are copied in place
// and regenerated by a pipeline run, so their contents change between deploys
// while their URLs do not. A cache-first branch under a hard-coded name served
// them indefinitely stale. Those entries are therefore stale-while-revalidate:
// the cached copy renders immediately and a background fetch refreshes it, so a
// returning visitor converges on the current build after one load.
self.addEventListener("install", (event) => {
  event.waitUntil(self.skipWaiting());
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) =>
        Promise.all(
          keys.filter((key) => key !== CACHE_NAME).map((key) => caches.delete(key)),
        ),
      )
      .then(() => self.clients.claim()),
  );
});

/** Only real assets are worth storing; see the rewrite fallback below. */
const isCacheable = (response) =>
  Boolean(response) &&
  response.ok &&
  response.type === "basic" &&
  !/text\/html/i.test(response.headers.get("content-type") || "");

self.addEventListener("fetch", (event) => {
  if (event.request.method !== "GET") return;
  const url = new URL(event.request.url);
  if (url.origin !== self.location.origin) return;

  const isNavigation = event.request.mode === "navigate" || url.pathname.endsWith("/index.html");
  if (url.pathname.endsWith("/sw.js")) {
    event.respondWith(fetch(event.request));
    return;
  }

  if (isNavigation) {
    event.respondWith(
      fetch(event.request)
        .then((response) => {
          if (!isCacheable(response)) return response;
          const copy = response.clone();
          event.waitUntil(
            caches
              .open(CACHE_NAME)
              .then((cache) => cache.put(event.request, copy))
              .catch(() => undefined),
          );
          return response;
        })
        .catch(() => caches.match(event.request)),
    );
    return;
  }

  event.respondWith(
    caches.open(CACHE_NAME).then((cache) =>
      cache.match(event.request).then((cached) => {
        const network = fetch(event.request)
          .then((response) => {
            if (isCacheable(response)) {
              const copy = response.clone();
              event.waitUntil(cache.put(event.request, copy).catch(() => undefined));
            }
            return response;
          })
          .catch(() => cached);

        return cached || network;
      }),
    ),
  );
});